import { z } from 'zod';

/**
 * A node in the page tree. `component` is either an antd component name
 * (e.g. "Button", "Form.Item") or the id of a custom component generated by the LLM.
 */
export interface BuilderNode {
  id: string;
  component: string;
  props: Record<string, unknown>;
  children: BuilderNode[];
}

export const builderNodeSchema: z.ZodType<BuilderNode> = z.lazy(() =>
  z.object({
    id: z.string(),
    component: z.string(),
    props: z.record(z.string(), z.unknown()),
    children: z.array(builderNodeSchema),
  }),
);

/** A custom (non-standard) component, generated by the LLM and stored with the project. */
export const customComponentSchema = z.object({
  id: z.string(),
  name: z.string(),
  description: z.string(),
  /** TSX source; must default-export a React component built from antd primitives. */
  source: z.string(),
  /** JSON schema of the props, so the editor can render a props panel. */
  propsSchema: z.record(z.string(), z.unknown()),
});
export type CustomComponent = z.infer<typeof customComponentSchema>;

export const pageSchema = z.object({
  id: z.string(),
  name: z.string(),
  root: builderNodeSchema,
});
export type Page = z.infer<typeof pageSchema>;

/**
 * Serializable theme. antd's `ThemeConfig` holds algorithm functions, so the project stores
 * the choices instead and `lib/theme` turns them into a `ThemeConfig`.
 */
export const projectThemeSchema = z.object({
  mode: z.enum(['light', 'dark']),
  compact: z.boolean(),
  /** antd seed token overrides, e.g. `{ colorPrimary: '#722ed1', borderRadius: 8 }`. */
  token: z.record(z.string(), z.union([z.string(), z.number()])),
});
export type ProjectTheme = z.infer<typeof projectThemeSchema>;

/**
 * Sample data standing in for an API response while mocking up a page. Component props can be
 * bound to it, and exported code declares it as a `const` named `name`.
 */
export const dataSourceSchema = z.object({
  id: z.string(),
  name: z.string(),
  data: z.json(),
  /** The API URL the data was imported from, if any. */
  url: z.string().optional(),
});
export type DataSource = z.infer<typeof dataSourceSchema>;

/** A fragment of page the user saved to reuse, listed under "My blocks" in the palette. */
export const customBlockSchema = z.object({
  id: z.string(),
  name: z.string().min(1),
  root: builderNodeSchema,
});
export type CustomBlock = z.infer<typeof customBlockSchema>;

/** A named snapshot of the project's content, restorable from the History panel. */
export const projectVersionSchema = z.object({
  id: z.string(),
  name: z.string().min(1),
  /** ISO 8601 timestamp. */
  createdAt: z.string(),
  root: builderNodeSchema,
  theme: projectThemeSchema,
  mockData: z.array(dataSourceSchema),
  customBlocks: z.array(customBlockSchema),
});
export type ProjectVersion = z.infer<typeof projectVersionSchema>;

export const projectSchema = z.object({
  version: z.literal(1),
  name: z.string(),
  theme: projectThemeSchema,
  pages: z.array(pageSchema),
  customComponents: z.array(customComponentSchema),
  /** Optional so project files saved before mock data existed still open. */
  mockData: z.array(dataSourceSchema).default([]),
  customBlocks: z.array(customBlockSchema).default([]),
  versions: z.array(projectVersionSchema).default([]),
});
export type Project = z.infer<typeof projectSchema>;
